mapper.select:
SELECT t.ID, ANY_VALUE(t.NAME) AS NAME, ANY_VALUE(t.SLUG) AS SLUG, ANY_VALUE(t.SEO_TITLE) AS SEO_TITLE, ANY_VALUE(t.SEO_KEYWORDS) AS SEO_KEYWORDS, ANY_VALUE(t.SEO_DESCRIPTION) AS SEO_DESCRIPTION, ANY_VALUE(t.SEO_SEARCH) AS SEO_SEARCH, ANY_VALUE(t.ENABLED) AS ENABLED, COUNT(atr.ARTICLE_ID) AS ARTICLE_COUNT FROM tag t LEFT JOIN article_tag_relation atr ON atr.TAG_ID = t.ID AND atr.DELETED = 0
AND t.NAME LIKE #{nameBind}
AND t.SLUG LIKE #{slugBind}
AND t.SEO_SEARCH = #{query.seoSearch}
AND t.ENABLED = #{query.enabled}
GROUP BY t.ID ORDER BY ARTICLE_COUNT DESC, t.ID DESC

SELECT t.ID, t.NAME, t.SLUG, t.ENABLED FROM tag t
AND t.NAME LIKE #{keywordBind}
ORDER BY t.NAME
